def none(reason='No additional replacement; inspected the executed harness and source', evidence=None):
    return dict(status='none_checked', items=[], unknown_boundaries=[], evidence=evidence or refs('baseline-browser.js','recovery-browser.js'), reason=reason)

def unknown(reason, boundaries):
    return dict(status='unknown',items=[],unknown_boundaries=boundaries,evidence=[],reason=reason)

def known(items,evidence,reason):
    return dict(status='known',items=items,unknown_boundaries=[],evidence=evidence,reason=reason)

def replacement(boundary,description,response,real,untested):
    return dict(boundary=boundary,description=description,behavior='replaced',configured_response=response,real_components=real,untested=untested)

