    c=dict(id=cid,module=module,required=required,scenario=scenario,expected=expected,actual=actual,evidence=evidence,status=status,reason='' if status in ('pass','fail') else actual,environment=env,driver='agent',evidence_type={'desktop_emulation':'emulation','static_review':'static','automated_test':'automated'}[env],level=level,behavior=scenario,capability_id=('CAP-'+engine.upper()) if engine else ('CAP-NODE' if env=='automated_test' else 'CAP-SOURCE'),build_id=b,configuration=dict(browser=engine or 'Node/source',version=baseline[engine]['version'] if engine else '',device='Linux desktop',os=platform.platform()),conditions=cond((engine+' '+baseline[engine]['version']) if engine else 'Node/source',scenario,[scenario]),depends_on=[],substitutions=dict(build=copy.deepcopy(fixture) if engine else none(evidence=refs('baseline-manifest.json','focused-tests.txt')),setup=copy.deepcopy(stripe) if engine else none(evidence=refs('focused-tests.txt')),additional=extra or none(evidence=evidence)),covers=covers or [])
    state['checks'].append(c);return c

